// Simple application for agent to work on
// Security-enhanced version with proper error handling and input validation

const express = require('express');
const app = express();

// ============================================
// SECURITY MIDDLEWARE CONFIGURATION
// ============================================

// Parse JSON with size limits (prevents DoS via large payloads)
app.use(express.json({ limit: '10kb' }));

// Parse URL-encoded data with size limits
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Security headers middleware
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});

// ============================================
// INPUT VALIDATION HELPERS
// ============================================

/**
 * Email validation function
 * @param {string} email - Email address to validate
 * @returns {boolean} - True if valid, false otherwise
 */
const isValidEmail = (email) => {
  if (!email || typeof email !== 'string') return false;
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email.trim());
};

/**
 * Name validation function
 * @param {string} name - Name to validate
 * @returns {boolean} - True if valid, false otherwise
 */
const isValidName = (name) => {
  if (!name || typeof name !== 'string') return false;
  const trimmed = name.trim();
  return trimmed.length >= 2 && trimmed.length <= 100;
};

/**
 * Validate user data object
 * @param {object} userData - User data to validate
 * @returns {object} - { valid: boolean, errors: string[] }
 */
const validateUserData = (userData) => {
  const errors = [];

  if (!userData || typeof userData !== 'object') {
    return { valid: false, errors: ['Invalid user data format'] };
  }

  if (userData.email && !isValidEmail(userData.email)) {
    errors.push('Invalid email address');
  }

  if (userData.name && !isValidName(userData.name)) {
    errors.push('Name must be between 2 and 100 characters');
  }

  return { valid: errors.length === 0, errors };
};

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// Custom error classes
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Global error-handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Handle custom application errors
  if (err instanceof AppError) {
    return res.status(err.statusCode).json({
      success: false,
      error: {
        message: err.message,
        status: err.statusCode,
      },
    });
  }

  // Handle validation errors
  if (err.errors) {
    return res.status(400).json({
      success: false,
      error: {
        message: 'Validation failed',
        details: err.errors,
      },
    });
  }

  // Handle URL-encoded errors
  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({
      success: false,
      error: {
        message: 'Invalid request format',
        status: 400,
      },
    });
  }

  // Handle JSON parsing errors
  if (err.type === 'entity.too.large') {
    return res.status(413).json({
      success: false,
      error: {
        message: 'Request payload too large',
        status: 413,
      },
    });
  }

  // Default to 500 for unexpected errors
  res.status(500).json({
    success: false,
    error: {
      message: process.env.NODE_ENV === 'production'
        ? 'Internal server error'
        : err.message,
      status: 500,
    },
  });
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: {
      message: `Route ${req.method} ${req.path} not found`,
      status: 404,
    },
  });
});

// ============================================
// ROUTES
