    //         message: 'Invalid query parameter',
    //         status: 400,
    //       },
    //     });
    //   }
    // }

    // Simulated response (normally from database)
    // Always return a sanitized version of the data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      success: true,
      data: users,
