// Secure application with proper error handling and input validation
// Security best practices implemented

const express = require('express');
const helmet = require('helmet');          // Security headers
const cors = require('cors');              // CORS configuration
const rateLimit = require('express-rate-limit');  // Rate limiting
const{xss} = require('express-xss-sanitizer');
const morgan = require('morgan');          // Request logging
const winston = require('winston');        // Structured logging

// Initialize Express app
const app = express();

// Configure security middleware
app.use(helmet({ contentSecurityPolicy: false }));  // CSP disabled for now - enable with care
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*',
  credentials: true,  // Set carefully - only needed for auth
}));
app.use((req, res, next) => {
  res.header('X-Frame-Options', 'DENY');
  res.header('X-Content-Type-Options', 'nosniff');
  res.header('X-XSS-Protection', '1; mode=block');
  next();
});
app.use(xss());  // Sanitize all inputs

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 minutes
  max: 100,                  // Limit each IP to 100 requests per window
  message: {
    error: 'Too many requests, please try again later.'
  },
  standardHeaders: true,       // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false,         // Disable `X-RateLimit-*` headers
});

// Apply to all API routes
app.use('/api/', limiter);

// Request logging with Winston
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

app.use(morgan('combined', { stream: { write: message => logger.info(message) } }));

// Request body parsing with size limits
const bodyLimit = '100kb';
app.use(express.json({ limit: bodyLimit }));
app.use(express.urlencoded({ extended: true, limit: bodyLimit }));

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'healthy',
      uptime: process.uptime(),
      timestamp: new Date().toISOString(),
      version: process.env.npm_package_version || 'unknown'
    });
  } catch (error) {
    logger.error('Health check error:', error);
    res.status(500).json({ error: 'Internal health check failure' });
  }
});

// User routes with input validation
const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const validateName = (name) => {
  // Allow letters, spaces, hyphens, apostrophes, minimal length
  return /^[a-zA-Z\s\-']+{2,50}$/.test(name);
};

// Example user data validation
const validateUserData = (userData) => {
  const errors = [];

  if (!userData?.name || typeof userData.name !== 'string') {
    errors.push('name is required and must be a string');
  } else if (!validateName(userData.name)) {
    errors.push('name is malformed');
  }

  if (!userData?.email || typeof userData.email !== 'string') {
    errors.push('email is required and must be a string');
  } else if (!validateEmail(userData.email)) {
    errors.push('email is malformed or invalid');
  }

  // Validate any other fields as needed
  if (errors.length > 0) {
    return { valid: false, errors };
  }

  return { valid: true, errors: [] };
};

// Users endpoint with robust error handling
app.get('/users', (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Log request context
    logger.info('Users endpoint accessed', {
      method: req.method,
      path: req.path,
      query: req.query,
      ip: req.ip,
      userAgent: req.get('User-Agent')
    });

    res.json({
      success: true,
      data: users,
      count: users.length,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    // Log errors but don't expose internals
    logger.error('Error in /users endpoint', {
      error: error.message,
      stack: error.stack,
      path: req.path,
      method: req.method
    });

    res.status(500).json({
      success: false,
      error: 'Internal server error'
    });
  }
});

// Example POST endpoint with validation and error handling
app.post('/users', express.raw({ type: 'application/json', limit: bodyLimit }), (req, res) => {
  try {
    const rawData = req.body.toString();
    let userData;

    // Parse and validate input
    try {
      userData = JSON.parse(rawData);
    } catch (parseError) {
      logger.warn('Invalid JSON in POST /users', { error: parseError.message });
      return res.status(400).json({
        success: false,
        error: 'Invalid JSON format',
        details: parseError.message
      });
    }

    const validation = validateUserData(userData);
    if (!validation.valid) {
      logger.warn('User data validation failed', { errors: validation.errors });
      return res.status(422).json({
        success: false,
        error: 'Validation failed',
        details: validation.errors
      });
    }

    // Business logic here...

    logger.info('New user created success', { email: userData.email });

    res.status(201).json({
      success: true,
      data: {
        id: Math.floor(Math.random() * 10000),  // In reality, use proper ID generation
        ...userData
      },
      message: 'User created successfully',
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    // Don't expose stack traces in production
    if (process.env.NODE_ENV !== 'development') {
      logger.error('Unexpected error in POST /users', {
        error: error.message,
        path: req.path,
        method: req.method
      });
    }

    res.status(500).json({
      success: false,
      error: 'Internal server error'
    });
  }
});

// Generic error handling middleware (must be last)
app.use((err, req, res, next) => {
  // Log the error
  logger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    body: req.body
  });

  // Send appropriate error response
  // Don't expose error details in production
  if (process.env.NODE_ENV !== 'production') {
    console.error('Error details:', err);
    return res.status(err.status || 500).json({
      success: false,
      error: err.message || 'Internal server error',
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
    });
  }

  res.status(err.status || 500).json({
    success: false,
    error: 'Internal server error'
  });
});

// 404 handler
app.use((req, res) => {
  logger.warn('Route not found', { path: req.path, method: req.method });

  res.status(404).json({
    success: false,
    error: 'Route not found',
    path: req.path
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully...');
  process.exit(0);
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully...');
  process.exit(0);
});

// Server start with safety checks
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

try {
  app.listen(PORT, HOST, () => {
    logger.info('Server started successfully', {
      port: PORT,
      host: HOST,
      environment: process.env.NODE_ENV || 'development'
    });
  });
} catch (error) {
  logger.error('Failed to start server', { error: error.message });
  process.exit(1);
}

module.exports = app;

