// Improved application with robust error handling and security best practices
const express = require('express');
const helmet = require('helmet');
const xss = require('xss-clean');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const MongoDBSanitize = require('express-mongo-sanitize');
const path = require('path');

// Initialize express app
const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Helmet - Security headers to help protect app from well-known web vulnerabilities
app.use(helmet());

// Rate limiting - Prevent brute force attacks and abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});
app.use('/api', limiter);

// Body parser - Parse incoming requests with JSON payloads
app.use(express.json({
  limit: '10kb', // Limit body size to prevent DoS attacks
  verify: (req, res, buf) => {
    // Cache buf to check malicious content
    req.rawBody = buf.toString('utf8');
  }
}));

// Body parser - Parse URL-encoded bodies
app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// Data sanitization against NoSQL injection
app.use(MongoDBSanitize());

// Data sanitization against XSS attacks
app.use(xss());

// ============================================
// SECURITY HEADERS & CONFIGURATION
// ============================================

// CORS configuration - restrict origins
const corsOptions = {
  origin: '*', // Configure actual allowed origins
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  preflightContinue: false,
  optionsSuccessStatus: 204
};
app.use(cors(corsOptions));

// Set secure cookie options (unless in development)
if (process.env.NODE_ENV !== 'development') {
  app.set('trust proxy', 1);
}

// ============================================
// APPLICATION MIDDLEWARE
// ============================================

// Request logging (in production, consider using a more secure logger)
app.use(morgan('combined')); // Replace with morgan('tiny') in development

// Custom middleware to log requests
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// Slashes - Redirect from trailing slashes for better SEO and avoid caching issues
app.use((req, res, next) => {
  // Only redirect the root path with optional trailing slash
  if (req.path === '/') {
    req.path = req.originalUrl === '/' ? '/' : `${req.originalUrl}/`;
  } else if (req.originalUrl.endsWith('/') && !req.originalUrl.endsWith('//')) {
    // Remove trailing slash for other routes (optional approach)
    const index = req.originalUrl.lastIndexOf('/');
    const originalPath = req.originalUrl.substring(0, index + 1);
    return res.redirect(301, originalPath);
  }

  next();
});

// ============================================
// HELPER FUNCTIONS
// ============================================

/**
 * Custom error handler
 * Wraps errors in a standard error object
 */
const errorHandler = (err, req, res, next) => {
  let error = { ...err };
  error.message = err.message;

  // Log the error for debugging (in production, use proper logging service)
  console.error('Error:', err);

  // Mongoose bad ObjectId - convert to 404 error
  if (err.name === 'CastError') {
    const message = 'Resource not found';
    error = { ...err, message, statusCode: 404 };
  }

  // Mongoose duplicate key handling
  if (err.code === 11000) {
    const message = 'Duplicate field value entered';
    error = { ...err, message, statusCode: 400 };
  }

  // Mongoose validation error
  if (err.name === 'ValidationError') {
    const message = Object.values(err.errors).map(val => val.message).join(', ');
    error = { ...err, message, statusCode: 400 };
  }

  // JWT errors
  if (err.name === 'JsonWebTokenError') {
    const message = 'Invalid token';
    error = { ...err, message, statusCode: 401 };
  }

  if (err.name === 'TokenExpiredError') {
    const message = 'Token expired';
    error = { ...err, message, statusCode: 401 };
  }

  // Default error
  res.status(error.statusCode || 500).json({
    success: false,
    error: error.message || 'Internal Server Error',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
};

/**
 * Async error handler wrapper
 * Wraps async route handlers to ensure errors are caught
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================
// ROUTE HANDLERS
// ============================================

// Health check endpoint - no authentication or validation needed
app.get('/health', asyncHandler(async (req, res) => {
  res.status(200).json({
    success: true,
    status: 'operational',
    environment: process.env.NODE_ENV || 'development',
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
    root: path.parse(__dirname).name
  });
}));

// Users endpoint with input validation
app.get('/users', asyncHandler(async (req, res) => {
  // Validate query parameters if present
  const { page = '1', limit = '10' } = req.query;

  // Basic validation for pagination parameters
  const validPage = parseInt(page, 10);
  const validLimit = parseInt(limit, 10);

  if (Number.isNaN(validPage) || validPage < 1) {
    return res.status(400).json({
      success: false,
      error: 'Invalid page number. Page must be a positive integer.'
    });
  }

  if (Number.isNaN(validLimit) || validLimit < 1 || validLimit > 100) {
    return res.status(400).json({
      success: false,
      error: 'Invalid limit. Limit must be between 1 and 100.'
    });
  }

  // Mock database query simulation
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Implement pagination logic here
  // const offset = (validPage - 1) * validLimit;
  // const paginatedUsers = await User.find().skip(offset).limit(validLimit);

  res.status(200).json({
    success: true,
    count: users.length,
    data: users,
    pagination: {
      page: validPage,
      limit: validLimit
    }
  });
}));

// Error boundary for 404 - must be last route
app.all('*', asyncHandler(async (req, res, next) => {
  return res.status(404).json({
    success: false,
    error: `Cannot find ${req.originalUrl} on this server.`
  });
}));

// Error handling middleware
app.use(errorHandler);

// ============================================
// GRACEFUL SHUTDOWN
// ============================================

let server;

const startServer = () => {
  const PORT = process.env.PORT || 3000;

  server = app.listen(PORT, () => {
    console.log(`🚀 Server running in ${process.env.NODE_ENV || 'development'} mode`);
    console.log(`📡 Listening on port ${PORT}`);
    console.log(`📍 Health check available at: http://localhost:${PORT}/health`);
  });

  // SIGTERM signal for graceful shutdown
