const app = express();

// ===== SECURITY MIDDLEWARE =====

// Helmet: Sets various HTTP headers for security
app.use(helmet({
  contentSecurityPolicy: false, // Set to true and configure if you use client-side code
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS middleware - configure appropriately for your environment
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*'); // Change to specific origin in production
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  if (req.method === 'OPTIONS') {
    res.sendStatus(200);
  } else {
    next();
  }
});

// Rate limiting - prevents brute force and DoS attacks
const rateLimitOptions = {
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
};

// Apply rate limiting to all routes
app.use(rateLimit(rateLimitOptions));

// Body parser middleware with limits
app.use(express.json({
  limit: '10kb', // Prevents large payloads
}));
app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// Sanitize input data (XSS protection)
app.use(xss());

// ===== ERROR HANDLING =====

// Custom error handler
app.use((err, req, res, next) => {
  console.error(err.stack); // Log error for debugging
  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined
  });
});

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// ===== ROUTES =====

// Health endpoint with proper validation
app.get('/health', (req, res) => {
  try {
    const timestamp = new Date().toISOString();
    res.json({
      status: 'ok',
      timestamp: timestamp,
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ status: 'error', message: 'Health check failed' });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if present
    const { page, limit } = req.query;

    if (page !== undefined) {
      const pageInt = parseInt(page, 10);
      if (!Number.isInteger(pageInt) || pageInt < 1) {
        return res.status(400).json({
          error: 'Bad request',
          message: 'Page must be a positive integer'
        });
      }
    }

    if (limit !== undefined) {
      const limitInt = parseInt(limit, 10);
      if (!Number.isInteger(limitInt) || limitInt < 1 || limitInt > 100) {
        return res.status(400).json({
          error: 'Bad request',
          message: 'Limit must be a positive integer between 1 and 100'
        });
      }
    }

    // Return sample data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      data: users,
      meta: {
        count: users.length
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to fetch users'
    });
  }
});

// ===== ERROR CATCHER FOR UNCAUGHT EXCEPTIONS =====

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // In production, you might want to gracefully shut down or perform cleanup
  process.exit(1);
});

process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  // In production, you might want to gracefully shut down or perform cleanup
  process.exit(1);
});

// Error handler middleware (must be last)
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: err.message || 'Internal server error',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// Helper function to validate user email
const validateEmail = (email) => {
  return validator.isEmail(email) && validator.trim(email);
};

// Helper function to validate email (for future endpoints)
const safeEmail = (email) => {
  if (!email || typeof email !== 'string') {
    return null;
  }
  const trimmed = email.trim();
  return validator.isEmail(trimmed) ? trimmed : null;
};

// Start the server with error handling
const PORT = process.env.PORT || 3000;

app.listen(PORT, (error) => {
  if (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

