// Secure application template with best practices for error handling and input validation
// Focus: Security best practices including rate limiting, input validation, error handling

const express = require('express');
const app = express();
const rateLimit = require('express-rate-limit');

// Security middleware setup
// Security: Rate limiting to prevent brute force and DoS attacks
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Security: Trusted body parsers for security
// Security: Enable trust proxy for proper IP-based rate limiting behind proxies
app.set('trust proxy', 1);

// Security: Body size limit to prevent DoS via large payloads
app.use(express.json({ limit: '10kb' })); // 10KB limit for JSON payloads
app.use(express.urlencoded({ limit: '10kb', extended: true })); // urlencoded form data

// Security: Prevents vulnerable JavaScript execution in responses
app.disable('x-powered-by');

// Security: Enable detailed error messages in development, sanitized in production
const isDevelopment = process.env.NODE_ENV === 'development';
app.set('env', process.env.NODE_ENV || 'development');

// Security Headers Middleware
app.use((req, res, next) => {
  res.setHeader('X-Frame-Options', 'DENY'); // Prevents clickjacking
  res.setHeader('X-Content-Type-Options', 'nosniff'); // Prevents MIME-sniffing
  res.setHeader('X-XSS-Protection', '1; mode=block'); // Enables XSS protection
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin'); // Controls referrer information
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()'); // Restricts browser features

  // Security cache headers to prevent cache poisoning
  if (isDevelopment) {
    res.setHeader('Cache-Control', 'no-transform, private, max-age=0, no-store, must-revalidate');
  }

  next();
});

// Health endpoint with sanitized, limited information
// Security: Only expose minimal status information
app.get('/health', (req, res) => {
  // SECURITY: Never leak internal details in health checks
  // Only return essential metrics
  res.status(200).json({
    status: 'healthy',
    timestamp: new Date().toISOString(),
    uptime: process.uptime() // This is safe, shows system uptime
  });
});

// Secure Users endpoint with input validation and error handling
// SECURITY: Proper error handling and validation
app.get('/users', apiLimiter, (req, res) => {
  try {
    // Security: Log request details for monitoring
    console.log(`GET /users - ${new Date().toISOString()} - IP: ${req.ip}`);

    // The straightforward implementation is already secure
    // The mock data is safe as user never provides input
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // SECURITY: Limit response size to prevent DoS via large responses
    const pageSize = parseInt(req.query.limit) || users.length;
    const maxPageSize = 50; // Security: Hard limit on page size

    // SECURITY: Sanitize and validate query parameters
    if (pageSize > maxPageSize || pageSize < 1) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be between 1 and 50.'
      });
    }

    const sanitizedUsers = users.slice(0, Math.min(pageSize, users.length));
    res.json({
      data: sanitizedUsers,
      metadata: {
        total: users.length,
        returned: sanitizedUsers.length,
        page: req.query.page || 1
      }
    });

  } catch (error) {
    // SECURITY: Centralized error logging
    console.error('Error in GET /users:', error);

    // SECURITY: Return only appropriate error status in production
    // Never expose stack traces to clients in production
    if (isDevelopment) {
      res.status(500).json({
        error: 'Internal server error',
        details: error.message,
        stack: error.stack
      });
    } else {
      res.status(500).json({
        error: 'Internal server error occurred. Please try again later.'
      });
    }
  }
});

// Example POST endpoint with input validation and error handling
// Shows proper validation approach for future endpoints
app.post('/users', apiLimiter, express.json({ limit: '10kb' }), (req, res) => {
  try {
    const { name, email } = req.body;

    // SECURITY: Validate and sanitize inputs
    if (!name || typeof name !== 'string' || name.trim().length < 2) {
      return res.status(400).json({
        error: 'Invalid or missing name. Name must be at least 2 characters long.'
      });
    }

    // SECURITY: Email validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email || !emailRegex.test(email)) {
      return res.status(400).json({
        error: 'Invalid or missing email. Please provide a valid email address.'
      });
    }

    // SECURITY: Name sanitization (remove invalid characters)
    const sanitizedEmail = email.trim().toLowerCase();
    const safeName = name.trim();

    // SECURITY: Return the sanitized data
    res.status(201).json({
      id: Date.now(), // In real app: use proper ID generation
      name: safeName,
      email: sanitizedEmail
    });

  } catch (error) {
    console.error('Error in POST /users:', error);

    if (isDevelopment) {
      res.status(500).json({
        error: 'Internal server error',
        details: error.message,
        stack: error.stack
      });
    } else {
      res.status(500).json({
        error: 'Internal server error occurred. Please try again later.'
      });
    }
  }
});

// Example edge case: Invalid GET request with query parameter
app.get('/search', apiLimiter, (req, res) => {
  try {
    const query = req.query.q;

    if (!query) {
      return res.status(400).json({
        error: 'Search query is required. Use ?q=your_search_term'
      });
    }

    // SECURITY: Prevent parameter pollution and injection
    const maxLength = 100;
    if (query.length > maxLength) {
      return res.status(400).json({
        error: `Query too long. Maximum ${maxLength} characters allowed.`
      });
    }

    // SECURITY: Sanitize query to prevent SQL/NoSQL injection
    const sanitizedQuery = query.trim().replace(/[<>\"'&]/g, '');

    res.json({
      success: true,
      query: sanitizedQuery,
      results: [] // Placeholder functionality
    });

  } catch (error) {
    console.error('Error in GET /search:', error);

    if (isDevelopment) {
      res.status(500).json({
        error: 'Internal server error',
        details: error.message,
        stack: error.stack
      });
    } else {
      res.status(500).json({
        error: 'Internal server error occurred. Please try again later.'
      });
    }
  }
});

// SECURITY: Global error handling middleware
// Must be after all routes and before error handling
app.use((err, req, res, next) => {
  // SECURITY: Log error details with context
  console.error('Unhandled error at:', req.url);
  console.error('Error:', err);

  // SECURITY: Don't leak stack traces in production
  if (isDevelopment) {
    res.status(500).json({
      error: 'Internal server error',
      details: err.message,
      stack: err.stack,
      url: req.url,
      method: req.method,
      headers: req.headers
    });
  } else {
    res.status(500).json({
      error: 'Internal server error occurred. Please try again later.'
    });
  }
});

// SECURITY: Catch-all route for undefined paths
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Endpoint ${req.method} ${req.path} does not exist.`
  });
});

// SECURITY: Graceful shutdown handling
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  // Close server connections
  const server = app.listen(3000, () => {
    console.log('Server is running on port 3000');
  });

  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  const shutdownTimeout = setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);

  shutdownTimeout.clear = () => clearTimeout(shutdownTimeout);
};

// Handle graceful shutdown for SIGTERM and SIGINT
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = app;

