const app = express();

// ===== SECURITY MIDDLEWARE =====

// Helmet mounts security HTTP headers
app.use(helmet());

// Rate limiting to prevent DDoS and brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, 
});
app.use(limiter);

// Data sanitization against XSS
app.use(xss());

// JSON body parsing with strict configuration
app.use(bodyParser.json({ limit: '10kb' }));
app.use(bodyParser.urlencoded({ limit: '10kb', extended: true }));

// ===== ERROR HANDLING MIDDLEWARE =====

// Centralized error handling
const errorHandler = (err, req, res, next) => {
  console.error('Error:', err);

  // Handle validation errors
  if (err instanceof ValidationError) {
    return res.status(400).json({
      error: 'Validation failed',
      details: err.details,
    });
  }

  // Handle JSON parsing errors
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Invalid JSON in request body',
    });
  }

  // Handle other errors
  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' ? 'An error occurred' : err.message,
  });
};

app.use(errorHandler);

// ===== INPUT VALIDATION SCHEMAS =====

const userSchema = Joi.object({
  name: Joi.string().min(1).max(100).required(),
  email: Joi.string().email().required(),
});

// ===== ROUTES =====

// Health check endpoint - no authentication required (for monitoring)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

// Users list endpoint
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Create user endpoint with validation
app.post('/users', [
  // Input validation
  body('name')
    .trim()
    .min(1)
    .max(100)
    .escape(), // specifically escapes HTML
  body('email')
    .isEmail()
    .normalizeEmail(), // Normalize email format
], async (req, res) => {
  // Check validation results
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      errors: errors.array(),
    });
  }

  // Create user (would be persistent in real app)
  const user = {
    id: Date.now(),
    name: req.body.name,
    email: req.body.email,
  };

  res.status(201).json({
    status: 'success',
    data: user,
  });
});

// 404 handler - catching all undefined routes
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
  });
});

// Graceful shutdown handler
const gracefulShutdown = () => {
  console.log('\nReceived shutdown signal');
  process.exit(0);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Start server with error handling
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

