// Request logging with security focus
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

app.use((req, res, next) => {
  logger.info({
    method: req.method,
    url: req.url,
    ip: req.ip,
    userAgent: req.get('user-agent')
  });
  next();
});

// Input validation middleware
const validateInput = (req, res, next) => {
  const errors = [];

  // Validate any URL parameters
  if (req.params) {
    Object.keys(req.params).forEach(key => {
      if (!validator.isEmpty(req.params[key])) {
        if (!validator.isAlphanumeric(req.params[key]) && !validator.isInt(req.params[key])) {
          errors.push(`Invalid parameter: ${key}`);
        }
      }
    });
  }

  // Validate Query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (req.query[key] && !validator.isEmpty(String(req.query[key]))) {
        if (!validator.isAlphanumeric(String(req.query[key]))) {
          errors.push(`Invalid query parameter: ${key}`);
        }
      }
    });
  }

  // Validate body data
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (!validator.isEmpty(String(req.body[key]))) {
        if (!validator.isAlphanumeric(String(req.body[key]))) {
          errors.push(`Invalid body field: ${key}`);
        }
      }
    });
  }

  if (errors.length > 0) {
    return res.status(400).json({
      success: false,
      error: 'Invalid input',
      details: errors
    });
  }

  next();
};

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    const validationErrors = validateInput(req, res, () => {});
    if (validationErrors) return; // validateInput already responded

    const healthStatus = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    logger.info({
      event: 'health_check',
      status: 'healthy'
    });

    res.json(healthStatus);

  } catch (error) {
    logger.error({
      event: 'health_check',
      error: error.message
    });
    res.status(500).json({
      success: false,
      error: 'Internal server error'
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', validateInput, (req, res, next) => {
  try {
    // Optional: Validate query parameters like ID filters if needed
    if (req.query.id && !validator.isInt(req.query.id)) {
      return res.status(400).json({
        success: false,
        error: 'Invalid user ID format. Must be an integer.'
      });
    }

    // Sanitize response data
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        createdAt: new Date().toISOString()
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        createdAt: new Date().toISOString()
      },
    ];

    res.json({
      success: true,
      data: users
    });

  } catch (error) {
    logger.error({
      event: 'get_users',
      error: error.message,
      stack: process.env.NODE_ENV === 'development' ? error.stack : undefined
    });
    next(error); // Pass to error handler
  }
});

// Error handling middleware - must be last
app.use((err, req, res, next) => {
  logger.error({
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  res.status(statusCode).json({
    success: false,
    error: err.message || 'Internal server error',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Route not found'
  });
});

// Start server with process.env configuration
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  logger.info({
    event: 'server_start',
    port: PORT,
    host: HOST,
    environment: process.env.NODE_ENV || 'development'
  });
});

module.exports = app;
```

