# Security Review: Error Handling and Input Validation

## Issues Identified

### 🚨 Critical Security Vulnerabilities

1. **No Input Validation** (CVE: Missing Validation)
   - All endpoints accept any input without validation
   - Could lead to injection attacks, buffer overflows, or unexpected behavior
   - GET requests from `req.query` are completely unvalidated

2. **No Rate Limiting** (CVE: Denial of Service)
   - No protection against brute force attacks
   - No protection against request flooding
   - Attackers can make unlimited requests

3. **No Content Security Policy** (CVE: XSS Vulnerability)
   - No headers to prevent Cross-Site Scripting attacks
   - Users can inject malicious scripts

4. **No CORS Protection** (CVE: Cross-Origin Attacks)
   - No CORS configuration
   - Any site can make requests to the API

### ⚠️ General Security Concerns

1. **JSON Response Handling**
   - No validation of data in user inputs
   - Could return invalid JSON due to malformed user data
   - Could leak sensitive information in error messages

2. **Port Binding**
   - Hardcoded port (3000) could be vulnerable if running as root
   - No input validation on port number

3. **Error Handling**
   - No centralized error handling
   - No error logging
   - Potential information disclosure through stack traces

---

## Recommended Improvements

### 1. Route-Level Input Validation

```javascript
// Example: User endpoint with validation
const Joi = require('joi');

const userSchema = Joi.object({
    name: Joi.string().min(1).max(100).required(),
    email: Joi.string().email().required()
});

app.get('/users', async (req, res) => {
    try {
        // Validate query parameters
        const { error, value } = userSchema.validate(req.query);

        if (error) {
            return res.status(400).json({
                error: 'Validation failed',
                details: error.details.map(d => d.message)
            });
        }

        // Only process validated data
        const users = [
            { id: 1, name: value.name || 'Alice', email: value.email || 'alice@example.com' },
            { id: 2, name: value.name || 'Bob', email: value.email || 'bob@example.com' }
        ];

        res.json(users);
    } catch (err) {
        next(err);
    }
});
```

### 2. Content Security Policy (CSP)

```javascript
// Before routes
app.use((req, res, next) => {
    res.setHeader('Content-Security-Policy',
        "default-src 'self'; " +
        "script-src 'self'; " +
        "style-src 'self' 'unsafe-inline'; " +
        "img-src 'self' data: https:; " +
        "font-src 'self'; " +
        "connect-src 'self';"
    );
    next();
});
```

### 3. CORS Configuration

```javascript
const allowedOrigins = ['https://yourdomain.com', 'https://app.example.com'];

app.use(cors({
    origin: function(origin, callback) {
        // Allow requests with no origin (mobile apps, curl requests)
        if (!origin) return callback(null, true);

        if (allowedOrigins.indexOf(origin) === -1) {
            const msg = 'CORS policy: Origin of origin not allowed';
            return callback(new Error(msg), false);
        }
        return callback(null, true);
    },
    credentials: true,
    maxAge: 86400 // 24 hours
}));
```

### 4. Rate Limiting

```javascript
const rateLimit = require('express-rate-limit');

// General API rate limiting
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
    standardHeaders: true,
    legacyHeaders: false,
    message: {
        error: 'Too many requests from this IP, please try again later.'
    }
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for /users endpoint
const userLimiter = rateLimit({
    windowMs: 60 * 60 * 1000, // 1 hour
    max: 20,
    message: 'Too many user operations, please try again later.'
});

app.get('/users', userLimiter, async (req, res) => {
    // ... existing code
});
```

### 5. Secure Error Handling Middleware

```javascript
// Centralized error handler
app.use((err, req, res, next) => {
    console.error('Error:', {
        message: err.message,
        stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
        timestamp: new Date().toISOString(),
        url: req.url,
        method: req.method
    });

    // Don't expose sensitive error details in production
    const statusCode = err.statusCode || 500;
    const message = process.env.NODE_ENV === 'development'
        ? err.message
        : 'An unexpected error occurred';

    res.status(statusCode).json({
        error: message,
        // Only include debug info in development
        ...(process.env.NODE_ENV === 'development' && { debug: err.stack })
    });
});

// 404 handler
app.use((req, res) => {
    res.status(404).json({
        error: 'Not found',
        path: req.path
    });
});
```

### 6. Environment-Based Configuration

```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

### 7. Helmet Middleware

```javascript
const helmet = require('helmet');

// Security headers
app.use(helmet({
    contentSecurityPolicy: process.env.NODE_ENV === 'development'
        ? false // Disable CSP in development
        : {
            directives: {
                defaultSrc: ["'self'"],
                scriptSrc: ["'self'"],
                styleSrc: ["'self'", "'unsafe-inline'"],
                imgSrc: ["'self'", "data:", "https:"],
                fontSrc: ["'self'"],
                connectSrc: ["'self'"],
            },
        },
    hsts: {
        maxAge: 31536000,
        includeSubDomains: true,
        preload: true
    }
}));
```

---

## Updated Secure Base Application

```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const Joi = require('joi');

const app = express();

// Security middleware
app.use(helmet({ contentSecurityPolicy: false })); // CSP disabled in dev only
app.use(cors({
    origin: process.env.ALLOWED_ORIGINS?.split(','),
    credentials: true,
}));
app.use(rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    message: { error: 'Too many requests, please try again later.' }
}));

// Centralized error handling
app.use((err, req, res, next) => {
    console.error('Error:', {
        message: err.message,
        stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
        timestamp: new Date().toISOString(),
        url: req.url,
        method: req.method
    });

    const statusCode = err.statusCode || 500;
    const message = process.env.NODE_ENV === 'development'
        ? err.message
        : 'An unexpected error occurred';

    res.status(statusCode).json({ error: message });
});

// Health endpoint with basic validation
app.get('/health', (req, res) => {
    try {
        const { latency } = req.query;
        if (latency && (Number(latency) < 0 || Number(latency) > 100000)) {
            return res.status(400).json({
                error: 'Invalid latency parameter'
            });
        }
        res.json({
            status: 'ok',
            timestamp: new Date().toISOString()
        });
    } catch (err) {
        next(err);
    }
});

// Users endpoint with validation
const userSchema = Joi.object({
    name: Joi.string().min(1).max(100).optional(),
    email: Joi.string().email().optional()
});

app.get('/users', async (req, res, next) => {
    try {
        const { error, value } = userSchema.validate(req.query);
        if (error) {
            return res.status(400).json({
                error: 'Validation failed',
                details: error.details.map(d => d.message)
            });
        }

        const result = [
            { id: 1, name: value.name || 'Alice', email: value.email || 'alice@example.com' },
            { id: 2, name: value.name || 'Bob', email: value.email || 'bob@example.com' }
        ];

        res.json(result);
    } catch (err) {
        next(err);
    }
});

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

app.listen(PORT, HOST, () => {
    console.log(`Server running on ${HOST}:${PORT}`);
    if (process.env.NODE_ENV === 'development') {
        console.log('❌ Development mode - Security headers disabled');
    }
});

module.exports = app;
```

---

## Package Dependencies to Install

```bash
npm install helmet cors express-rate-limit joi dotenv
```

---

## .env Configuration Example

```
NODE_ENV=production
PORT=3000
HOST=0.0.0.0
ALLOWED_ORIGINS=https://yourdomain.com,https://app.example.com
```

---

## Testing Checklist

- [ ] Validate all input parameters
- [ ] Test with malformed input
- [ ] Verify error messages don't leak sensitive info (in production)
- [ ] Test rate limiting
- [ ] Verify CORS headers
- [ ] Check Content Security Policy headers
- [ ] Test security headers (Helmet)
- [ ] Verify error handling middleware
- [ ] Test 404 routes
- [ ] No sensitive information in logs

