// Enhanced application with security best practices
// This version includes comprehensive error handling and input validation

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const sanitizeHtml = require('sanitize-html');
const morgan = require('morgan');

const app = express();

// ============ Security Middleware ============

// Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: false, // Disable CSP to avoid self-injection issues
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests',
      message: 'Please try again later'
    });
  }
});
app.use('/api/', limiter);

// Request logging in development
if (process.env.NODE_ENV === 'development') {
  app.use(morgan('dev'));
}

// Body parser with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Invalid request',
      details: errors.array()
    });
  }
  next();
};

// HTML sanitization helper
const sanitizeInput = (input) => {
  return typeof input === 'string'
    ? sanitizeHtml(input, {
        allowedTags: [],
        allowedAttributes: {}
      })
    : input;
};

// ============ Routes ============

// Health check endpoint
app.get('/health', (req, res, next) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with validation
app.get('/users', (req, res, next) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  } catch (error) {
    next(error);
  }
});

app.post('/users', [
  // Validation rules
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .notEmpty()
    .withMessage('Name is required and must be between 1-100 characters'),
  body('email')
    .trim()
    .isEmail()
    .normalizeEmail()
    .withMessage('Valid email is required'),
  validateRequest
], (req, res, next) => {
  try {
    // Sanitize input
    const sanitizedUser = {
      name: sanitizeInput(req.body.name),
      email: sanitizeInput(req.body.email)
    };

    // In a real application, you would:
    // 1. Check if email already exists in database
    // 2. Hash password (if applicable)
    // 3. Store validated data in database
    // 4. Return proper success response

    console.log('User created:', sanitizedUser);
    res.status(201).json({
      success: true,
      message: 'User created successfully',
      user: {
        name: sanitizedUser.name,
        email: sanitizedUser.email
      }
    });
  } catch (error) {
    next(error);
  }
});

// ============ Error Handling ============

// 404 handler - must be after all routes
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    path: req.path
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method
  });

  // Database or internal errors
  if (err.code) {
    res.status(500).json({
      error: 'Database Error',
      message: process.env.NODE_ENV === 'development' ? err.message : 'Internal server error'
    });
  }
  // Known validation errors (should be handled by validation middleware)
  else if (err.status === 400) {
    res.status(400).json(err);
  }
  // Default to 500 server error
  else {
    res.status(500).json({
      error: 'Internal Server Error',
      message: process.env.NODE_ENV === 'development' ? err.message : 'Something went wrong'
    });
  }
});

// ============ Server Configuration ============

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  process.exit(0);
});

module.exports = app;

